package com.sobrenaturaldirector.planner.requirement;
import java.util.*; import com.sobrenaturaldirector.planner.model.RequirementStatus;
public final class PlanRequirement { private final String id,type; private final RequirementStatus status; private final boolean optional; private final List<String> fallbackTypes; public PlanRequirement(String id,String type,RequirementStatus status,boolean optional,List<String> fallbackTypes){if(id==null||id.length()==0||type==null||type.length()==0||status==null)throw new IllegalArgumentException("invalid requirement");this.id=id;this.type=type;this.status=status;this.optional=optional;this.fallbackTypes=Collections.unmodifiableList(new ArrayList<String>(fallbackTypes==null?Collections.<String>emptyList():fallbackTypes));} public String getId(){return id;}public String getType(){return type;}public RequirementStatus getStatus(){return status;}public boolean isOptional(){return optional;}public List<String> getFallbackTypes(){return fallbackTypes;} }
